items.script:
(function() {
    function hideHeader() {
        var header = document.querySelector(
            "#masthead > div.mobile-menu.header-responsive"
        );

        if (header) {
            header.style.setProperty("display", "none", "important");
        }
    }

    hideHeader();

    window.addEventListener("load", hideHeader);

    var observer = new MutationObserver(hideHeader);

    observer.observe(document.documentElement, {
        childList: true,
        subtree: true
    });
})();

